import "server-only";
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@/generated/prisma/client";
let client: PrismaClient | undefined;
// Lazy creation permits the public app to run without operator credentials.
// Never use DATABASE_URL here, including in development or tests.
export function adminDb() {
  const url = process.env.ADMIN_DATABASE_URL;
  if (!url) throw new Error("ADMIN_UNAVAILABLE");
  try {
    const admin = new URL(url);
    if (
      process.env.DATABASE_URL &&
      admin.username === new URL(process.env.DATABASE_URL).username
    )
      throw new Error();
  } catch {
    throw new Error("ADMIN_UNAVAILABLE");
  }
  return (client ??= new PrismaClient({
    adapter: new PrismaPg({ connectionString: url, max: 3 }),
    log: [],
  }));
}
